#pragma once

#include "ScheduledExecutorService.h"

#include <cstddef>

// java.util.concurrent.ScheduledThreadPoolExecutor 桩。
// 直接继承 ScheduledExecutorService 的实现，仅补充 removeOnCancel 策略开关：
// 桩实现中取消即标记跳过（任务本体不会执行），天然满足移除语义，因此仅记录开关值。
class ScheduledThreadPoolExecutor : public ScheduledExecutorService {
public:
    explicit ScheduledThreadPoolExecutor(std::size_t corePoolSize)
        : ScheduledExecutorService(corePoolSize) {}

    // Java 语义：任务取消后是否立即从工作队列移除；此处为空实现（仅记录）
    void setRemoveOnCancelPolicy(bool value) { removeOnCancel_ = value; }
    bool getRemoveOnCancelPolicy() const { return removeOnCancel_; }

    void shutdown() override { ScheduledExecutorService::shutdown(); }

private:
    bool removeOnCancel_ = false;
};
